// Isolated local-Anvil coverage for the testnet deployment executor. No live RPC.
//
// Scenarios: interruption after signed bytes (1), interruption after the attempt record
// with a dropped broadcast response (2), resume after inclusion/finality without a new
// nonce, replacement or second send (3), fail-closed corrupt/wrong/altered evidence (4),
// and an older attempted creation still pending (5). Every signed creation is generated by
// the reviewed planner against the pinned test-only bundle; nothing here touches Monad.
import assert from "node:assert/strict";
import { access, cp, mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { createHash } from "node:crypto";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { createServer } from "node:net";
import { createServer as createHttpServer } from "node:http";
import { spawn } from "node:child_process";
import { once } from "node:events";
import { setTimeout as delay } from "node:timers/promises";
import { ContractFactory, HDNodeWallet, JsonRpcProvider, keccak256 } from "ethers";
import solc from "solc";
import { prepareTestnetDeployment } from "./prepare-testnet-deployment.mjs";
import { submitTestnetDeployment } from "./submit-testnet-deployment.mjs";

const root = fileURLToPath(new URL("../../../", import.meta.url));
const bundle = process.env.EREBUS_M5_TEST_BUNDLE;
const pin = process.env.EREBUS_M5_TEST_BUNDLE_SHA256;

const digest = (bytes) => createHash("sha256").update(bytes).digest("hex");
const exists = (path) => access(path).then(() => true, () => false);
const readJson = async (path) => JSON.parse(await readFile(path, "utf8"));

async function reservePort() {
  const server = createServer();
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  const { port } = server.address();
  await new Promise((done) => server.close(done));
  return port;
}

// One JSON-RPC hop in front of Anvil. Hooks may drop a response, replace its result or
// return a JSON-RPC error while the upstream request is still forwarded first. Ethers sees
// only the proxy envelope, so the retained journal records what a real interruption leaves.
async function startProxy(upstream, hook) {
  const state = { sends: 0, calls: 0 };
  const server = createHttpServer((request, response) => {
    let body = "";
    request.on("data", (chunk) => { body += chunk; });
    request.on("end", async () => {
      state.calls += 1;
      let envelope;
      try { envelope = JSON.parse(body); } catch { response.writeHead(400); response.end(); return; }
      if (envelope.method === "eth_sendRawTransaction") state.sends += 1;
      const reply = (payload) => {
        response.writeHead(200, { "content-type": "application/json" });
        response.end(JSON.stringify(payload));
      };
      try {
        const forwarded = await fetch(upstream, {
          method: "POST", headers: { "content-type": "application/json" }, body,
        });
        const text = await forwarded.text();
        const decision = hook ? await hook(envelope.method, envelope.params) : null;
        if (decision?.drop) { response.writeHead(502); response.end(); return; }
        if (decision?.error) {
          reply({ jsonrpc: "2.0", id: envelope.id, error: { code: -32000, message: decision.error } });
          return;
        }
        const parsed = JSON.parse(text);
        if (decision?.replace !== undefined) parsed.result = decision.replace;
        reply(parsed);
      } catch { response.writeHead(502); response.end(); }
    });
  });
  await new Promise((done) => server.listen(0, "127.0.0.1", done));
  const { port } = server.address();
  return {
    url: `http://127.0.0.1:${port}`,
    state,
    close: () => new Promise((done) => server.close(done)),
  };
}

async function withMining(provider, milliseconds, work) {
  let mining = false;
  const timer = setInterval(async () => {
    if (mining) return;
    mining = true;
    try { await provider.send("evm_mine", []); } finally { mining = false; }
  }, milliseconds);
  try { return await work(); } finally { clearInterval(timer); }
}

async function withTimeout(promise, milliseconds, label) {
  let timer;
  try {
    return await Promise.race([
      promise,
      new Promise((_, reject) => { timer = setTimeout(() => reject(new Error(`${label} exceeded ${milliseconds} ms`)), milliseconds); }),
    ]);
  } finally { clearTimeout(timer); }
}

if (!bundle || !pin) {
  console.log("executor interruption tests not run; set both explicit bundle variables");
  process.exit(0);
}

const port = await reservePort();
const upstream = `http://127.0.0.1:${port}`;
const anvil = spawn("anvil", ["--host", "127.0.0.1", "--port", String(port), "--chain-id", "10143",
  "--slots-in-an-epoch", "1", "--silent"], { stdio: "ignore" });
const stopped = once(anvil, "exit");
const provider = new JsonRpcProvider(upstream, undefined, { cacheTimeout: -1 });
const scratch = [];
try {
  let ready = false;
  for (let attempt = 0; attempt < 100; attempt++) {
    try { await provider.getBlockNumber(); ready = true; break; } catch { await delay(50); }
  }
  assert(ready, "local Anvil startup failed");
  const worker = HDNodeWallet.fromPhrase("test test test test test test test test test test test junk");
  const localSigner = await provider.getSigner(0);
  assert.equal(await localSigner.getAddress(), worker.address, "unexpected local signer");

  const sources = {};
  for (const name of ["MockERC20", "MockWMON"]) {
    sources[`${name}.sol`] = { content: await readFile(resolve(root, `contracts/evm/src/${name}.sol`), "utf8") };
  }
  const compiled = JSON.parse(solc.compile(JSON.stringify({ language: "Solidity", sources,
    settings: { evmVersion: "paris", outputSelection: { "*": { "*": ["abi", "evm.bytecode.object"] } } } })));
  assert(!compiled.errors?.some((error) => error.severity === "error"));
  const signer = await provider.getSigner(0);
  const assets = [];
  for (const [name, source, args] of [["erc20", "MockERC20", ["Test", "TEST"]], ["wmon", "MockWMON", []]]) {
    const artifact = compiled.contracts[`${source}.sol`][source];
    const token = await new ContractFactory(artifact.abi, artifact.evm.bytecode.object, signer).deploy(...args);
    await token.waitForDeployment();
    const address = await token.getAddress();
    assets.push({ name, address, runtime_keccak256: keccak256(await provider.getCode(address)).slice(2) });
  }
  for (let count = 0; count < 4; count++) await provider.send("evm_mine", []);

  const base = { version: 1, test_only: true, chain_id: 10143, bundle_dir: bundle, manifest_sha256: pin,
    deployer: worker.address, starting_nonce: 0, assets };
  const directories = resolve(tmpdir(), `erebus-submit-tests-${Date.now()}`);
  scratch.push(directories);
  await rm(directories, { recursive: true, force: true });
  await mkdir(directories, { recursive: true });

  async function makeRun(label, startingNonce) {
    const plan = await prepareTestnetDeployment({ ...base, starting_nonce: startingNonce });
    const bytes = Buffer.from(JSON.stringify(plan));
    const directory = await mkdtemp(resolve(directories, `${label}-`));
    const planFile = resolve(directory, "prepared.json");
    const keyFile = resolve(directory, "worker.key");
    await writeFile(planFile, bytes, { flag: "wx", mode: 0o600 });
    await writeFile(keyFile, Buffer.from(worker.privateKey.slice(2), "hex"), { flag: "wx", mode: 0o600 });
    return { directory, plan, bytes, sha256: digest(bytes), planFile, keyFile, journal: resolve(directory, "journal") };
  }

  async function proxies(primaryHook, peerHook) {
    const primary = await startProxy(upstream, primaryHook || null);
    const peer = await startProxy(upstream, peerHook || null);
    return { primary, peer, urls: [primary.url, peer.url], close: async () => { await primary.close(); await peer.close(); } };
  }

  // Scenario 1: signed bytes persisted, no attempt. The failure lands on the second
  // pending-nonce read, exactly between the durable signed record and the attempt record.
  {
    const run = await makeRun("s1", await provider.getTransactionCount(worker.address));
    let nonceReads = 0;
    const hops = await proxies((method, params) => {
      if (method === "eth_getTransactionCount" && params[1] === "pending") {
        nonceReads += 1;
        if (nonceReads === 2) return { error: "injected interruption before attempt" };
      }
      return null;
    });
    try {
      await assert.rejects(withMining(provider, 500, () => withTimeout(
        submitTestnetDeployment(run.planFile, run.sha256, run.keyFile, run.journal, hops.urls, true),
        60_000, "s1")), /interruption/);
    } finally { await hops.close(); }
    assert.equal(hops.primary.state.sends, 0, "interrupted run must not broadcast");
    assert(await exists(resolve(run.journal, "0-signed.json")), "signed bytes must be durable");
    assert(!await exists(resolve(run.journal, "0-attempt.json")), "no attempt may exist");
    assert(!await exists(resolve(run.journal, "0-finalized.json")));
    const retained = await readFile(resolve(run.journal, "0-signed.json"), "utf8");

    const clean = await proxies();
    const hashes = await withMining(provider, 400, () => withTimeout(
      submitTestnetDeployment(run.planFile, run.sha256, run.keyFile, run.journal, clean.urls, true),
      180_000, "s1-resume"));
    await clean.close();
    assert.equal(hashes.length, 6);
    assert.equal(await readFile(resolve(run.journal, "0-signed.json"), "utf8"), retained,
      "resume re-signed instead of reusing retained bytes");
    assert.equal(clean.primary.state.sends, 6, "resume must broadcast each call exactly once");
    console.log(JSON.stringify({ status: "s1", resumed_sends: clean.primary.state.sends, re_signed: false }));
  }

  // Scenario 2: attempt record durable, broadcast response dropped while the transaction
  // still lands. Resume must observe it and never send a second transaction for call 0.
  const dropped = await makeRun("s2", await provider.getTransactionCount(worker.address));
  {
    const bogus = `0x${"ff".repeat(32)}`;
    const hops = await proxies((method) => method === "eth_sendRawTransaction" ? { replace: bogus } : null);
    try {
      await assert.rejects(withTimeout(
        submitTestnetDeployment(dropped.planFile, dropped.sha256, dropped.keyFile, dropped.journal, hops.urls, true),
        60_000, "s2"), /ambiguous broadcast hash/);
    } finally { await hops.close(); }
    assert.equal(hops.primary.state.sends, 1, "the dropped response still reached the chain");
    const signed = await readJson(resolve(dropped.journal, "0-signed.json"));
    const attempt = await readJson(resolve(dropped.journal, "0-attempt.json"));
    assert.equal(attempt.hash, signed.hash);
    assert(!await exists(resolve(dropped.journal, "0-finalized.json")));
    const receipt = await provider.getTransactionReceipt(signed.hash);
    assert(receipt && BigInt(receipt.status) === 1n, "dropped-response transaction must have landed");
    const clean = await proxies();
    const hashes = await withMining(provider, 400, () => withTimeout(
      submitTestnetDeployment(dropped.planFile, dropped.sha256, dropped.keyFile, dropped.journal, clean.urls, true),
      180_000, "s2-resume"));
    await clean.close();
    assert.equal(hashes[0], signed.hash);
    assert.equal(clean.primary.state.sends, 5, "call 0 must not be broadcast twice on resume");
    console.log(JSON.stringify({ status: "s2", resume_sends: clean.primary.state.sends, call0_resent: false }));
  }

  // Scenario 3: resuming a fully finalized journal changes nothing on chain.
  {
    const before = await provider.getTransactionCount(worker.address);
    const clean = await proxies();
    const hashes = await withTimeout(
      submitTestnetDeployment(dropped.planFile, dropped.sha256, dropped.keyFile, dropped.journal, clean.urls, true),
      60_000, "s3");
    await clean.close();
    assert.equal(clean.primary.state.sends, 0, "finalized resume must not send");
    assert.equal(await provider.getTransactionCount(worker.address), before, "finalized resume changed the nonce");
    assert.deepEqual(hashes, await readJson(resolve(dropped.journal, "hashes.json")));
    for (const call of dropped.plan.calls) {
      const code = await provider.getCode(call.predicted_address);
      assert.equal(keccak256(code), call.runtime_keccak256, "replacement deployment detected");
    }
    console.log(JSON.stringify({ status: "s3", resume_sends: 0, nonce_advanced: false }));
  }

  const scenario4 = async () => {
    // 4a: wrong plan pin, fresh journal.
    const wrongPinRun = await makeRun("s4a", await provider.getTransactionCount(worker.address));
    const hopsA = await proxies();
    try {
      await assert.rejects(
        submitTestnetDeployment(wrongPinRun.planFile, "00".repeat(32), wrongPinRun.keyFile, wrongPinRun.journal, hopsA.urls, true),
        /pin mismatch/);
    } finally { await hopsA.close(); }
    assert.equal(hopsA.primary.state.sends, 0);

    // 4b: a different pinned plan into a retained journal.
    const other = await makeRun("s4b", await provider.getTransactionCount(worker.address));
    const hopsB = await proxies();
    try {
      await assert.rejects(
        submitTestnetDeployment(other.planFile, other.sha256, other.keyFile, dropped.journal, hopsB.urls, true),
        /different plan/);
    } finally { await hopsB.close(); }
    assert.equal(hopsB.primary.state.sends, 0);

    // 4c: corrupt and altered retained records in copied journals.
    for (const [label, mutate] of [
      ["truncated-signed", async (journal) => writeFile(resolve(journal, "0-signed.json"), "{")],
      ["truncated-plan", async (journal) => writeFile(resolve(journal, "plan.json"), "{\"sha256\":")],
      ["altered-raw", async (journal) => {
        const record = await readJson(resolve(journal, "0-signed.json"));
        record.raw = `${record.raw.slice(0, -2)}${record.raw.endsWith("00") ? "01" : "00"}`;
        await writeFile(resolve(journal, "0-signed.json"), JSON.stringify(record));
      }],
      ["altered-attempt", async (journal) => {
        const record = await readJson(resolve(journal, "0-attempt.json"));
        record.hash = `0x${"22".repeat(32)}`;
        await writeFile(resolve(journal, "0-attempt.json"), JSON.stringify(record));
      }],
    ]) {
      const copy = await mkdtemp(resolve(directories, `s4c-${label}-`));
      await cp(dropped.journal, resolve(copy, "journal"), { recursive: true });
      await mutate(resolve(copy, "journal"));
      const hops = await proxies();
      try {
        await assert.rejects(withTimeout(
          submitTestnetDeployment(dropped.planFile, dropped.sha256, dropped.keyFile, resolve(copy, "journal"), hops.urls, true),
          30_000, `s4c-${label}`));
      } finally { await hops.close(); }
      assert.equal(hops.primary.state.sends, 0, `${label} must fail closed without sending`);
    }

    // 4d: conflicting receipts between the two providers.
    {
      const copy = await mkdtemp(resolve(directories, "s4d-"));
      await cp(dropped.journal, resolve(copy, "journal"), { recursive: true });
      const signed = await readJson(resolve(dropped.journal, "0-signed.json"));
      const hops = await proxies(null, (method, params) => {
        if (method === "eth_getTransactionReceipt" && params[0] === signed.hash) {
          return { replace: { status: "0x1", blockHash: `0x${"33".repeat(32)}`, blockNumber: "0x1",
            to: null, from: worker.address, contractAddress: dropped.plan.calls[0].predicted_address,
            transactionHash: signed.hash } };
        }
        return null;
      });
      try {
        await assert.rejects(withTimeout(
          submitTestnetDeployment(dropped.planFile, dropped.sha256, dropped.keyFile, resolve(copy, "journal"), hops.urls, true),
          30_000, "s4d"), /receipts disagree/);
      } finally { await hops.close(); }
      assert.equal(hops.primary.state.sends, 0);
    }

    // 4e: conflicting runtime evidence for a planned creation.
    {
      const copy = await mkdtemp(resolve(directories, "s4e-"));
      await cp(dropped.journal, resolve(copy, "journal"), { recursive: true });
      const expected = dropped.plan.calls[0].predicted_address.toLowerCase();
      const hops = await proxies(null, (method, params) => {
        if (method === "eth_getCode" && params[0].toLowerCase() === expected) return { replace: "0x00" };
        return null;
      });
      try {
        await assert.rejects(withTimeout(
          submitTestnetDeployment(dropped.planFile, dropped.sha256, dropped.keyFile, resolve(copy, "journal"), hops.urls, true),
          30_000, "s4e"), /runtime mismatch/);
      } finally { await hops.close(); }
      assert.equal(hops.primary.state.sends, 0);
    }
    console.log(JSON.stringify({ status: "s4", cases: 7, sends: 0 }));
  };
  await scenario4();

  const scenario5 = async () => {
    await provider.send("anvil_setAutomine", [false]);
    const pending = await makeRun("s5", await provider.getTransactionCount(worker.address));
    const bogus = `0x${"ff".repeat(32)}`;
    const hops = await proxies((method) => method === "eth_sendRawTransaction" ? { replace: bogus } : null);
    try {
      await assert.rejects(withTimeout(
        submitTestnetDeployment(pending.planFile, pending.sha256, pending.keyFile, pending.journal, hops.urls, true),
        60_000, "s5"), /ambiguous broadcast hash/);
    } finally { await hops.close(); }
    const signed = await readJson(resolve(pending.journal, "0-signed.json"));
    assert.equal(hops.primary.state.sends, 1);
    assert.equal(await provider.getTransactionCount(worker.address), pending.plan.calls[0].nonce);
    assert.equal(await provider.getTransactionCount(worker.address, "pending"), pending.plan.calls[0].nonce + 1);
    assert.equal(await provider.getTransactionReceipt(signed.hash), null, "creation must still be pending");

    // 5a: while call 0 is pending, resume may not advance or send. The receipt read is
    // interrupted, so the pending observation fails closed instead of advancing the plan.
    const blocked = await proxies((method) => method === "eth_getTransactionReceipt"
      ? { error: "injected interruption during pending resume" } : null);
    try {
      await assert.rejects(withTimeout(
        submitTestnetDeployment(pending.planFile, pending.sha256, pending.keyFile, pending.journal, blocked.urls, true),
        60_000, "s5a"), /interruption/);
    } finally { await blocked.close(); }
    assert.equal(blocked.primary.state.sends, 0, "pending resume must not send");
    assert(!await exists(resolve(pending.journal, "1-signed.json")), "pending resume advanced to call 1");
    assert.equal((await readJson(resolve(pending.journal, "0-attempt.json"))).hash, signed.hash);

    // 5c: once the pending creation is mined, the original journal resumes without a
    // replacement or a second send and completes the remaining plan.
    await provider.send("anvil_setAutomine", [true]);
    await provider.send("evm_mine", []);
    const finalized = await provider.getTransactionReceipt(signed.hash);
    assert(finalized && BigInt(finalized.status) === 1n, "pending creation did not finalize");
    const retained = await readFile(resolve(pending.journal, "0-signed.json"), "utf8");
    const clean = await proxies();
    const hashes = await withMining(provider, 300, () => withTimeout(
      submitTestnetDeployment(pending.planFile, pending.sha256, pending.keyFile, pending.journal, clean.urls, true),
      180_000, "s5c"));
    await clean.close();
    assert.equal(hashes[0], signed.hash);
    assert.equal(await readFile(resolve(pending.journal, "0-signed.json"), "utf8"), retained, "resume replaced retained bytes");
    assert.equal(clean.primary.state.sends, 5, "call 0 must not be resent after finality");
    assert.equal(await provider.getTransactionCount(worker.address), pending.plan.calls[0].nonce + 6);
    console.log(JSON.stringify({ status: "s5", resume_sends_after_finality: clean.primary.state.sends,
      call0_resent: false }));

    // 5b: a new plan whose starting nonce skips an older pending attempted creation must be
    // refused. This is the reproducer for the reported executor defect; it fails until the
    // executor checks the mined nonce instead of only the pending count.
    await provider.send("anvil_setAutomine", [false]);
    const older = await makeRun("s5b-older", await provider.getTransactionCount(worker.address));
    const olderHops = await proxies((method) => method === "eth_sendRawTransaction" ? { replace: bogus } : null);
    try {
      await assert.rejects(withTimeout(
        submitTestnetDeployment(older.planFile, older.sha256, older.keyFile, older.journal, olderHops.urls, true),
        60_000, "s5b-older"), /ambiguous broadcast hash/);
    } finally { await olderHops.close(); }
    assert.equal(olderHops.primary.state.sends, 1);
    const olderNonce = older.plan.calls[0].nonce;
    assert.equal(await provider.getTransactionCount(worker.address, "pending"), olderNonce + 1);

    const skip = await makeRun("s5b-skip", olderNonce + 1);
    const skipHops = await proxies((method) => method === "eth_sendRawTransaction" ? { replace: bogus } : null);
    try {
      await assert.rejects(withTimeout(submitTestnetDeployment(skip.planFile, skip.sha256, skip.keyFile, skip.journal,
        skipHops.urls, true), 60_000, "s5b-skip"), /older unmined transaction holds the deployment lane/);
    } finally { await skipHops.close(); }
    assert.equal(skipHops.primary.state.sends, 0,
      `reproducer: a new plan at starting_nonce ${olderNonce + 1} bypassed the older pending attempted ` +
      `creation at nonce ${olderNonce}; observed ${skipHops.primary.state.sends} broadcast(s). ` +
      "The executor compares only eth_getTransactionCount(pending) with the starting nonce, so it cannot " +
      "see that the pending count is inflated by a foreign retained attempt.");
    assert(!await exists(resolve(skip.journal, "0-signed.json")), "foreign pending creation must prevent signing");
    assert(!await exists(resolve(skip.journal, "0-attempt.json")), "foreign pending creation must prevent an attempt");
    console.log(JSON.stringify({ status: "s5b", sends: 0, signed: false, attempted: false }));
  };
  await scenario5();

  console.log("executor interruption, resume and fail-closed coverage passed against local Anvil");
} finally {
  provider.destroy();
  if (anvil.exitCode === null) anvil.kill("SIGTERM");
  await stopped;
  for (const directory of scratch) await rm(directory, { recursive: true, force: true });
}
